package com.yuegang.zhihui.ai.infrastructure;import com.yuegang.zhihui.ai.application.AiGovernanceService;import com.yuegang.zhihui.ai.domain.ModelAnswer;import com.yuegang.zhihui.ai.domain.ModelGateway;public final class GovernedModelGateway implements ModelGateway{private final ModelGateway delegate;private final AiGovernanceService governance;public GovernedModelGateway(ModelGateway d,AiGovernanceService g){delegate=d;governance=g;}public String answer(String runtime,String user){return delegate.answer(system(runtime),user);}public ModelAnswer answerWithSources(String runtime,String user){return delegate.answerWithSources(system(runtime),user);}public String modelName(){return delegate.modelName();}public boolean available(){return delegate.available();}public boolean supportsWebSearch(){return delegate.supportsWebSearch();}private String system(String runtime){return governance.activeSystemPrompt()+"\n\n"+runtime;}}
